head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vFrnidsApplStatCd = "1"; // 신청상태
scwin.obj_left = 0;
scwin.obj_top = 0;
// var vMktactCd = '309';          //채권시장조치구분코드
scwin.processGp;
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.bns.BnsPanelToGroupBox(pnl_Req); // 패널라운드처리(신청)
        $c.bns.BnsPanelToGroupBox(pnl_Acpt); // 패널라운드처리(접수)
        $c.bns.BnsPanelToGroupBox(panel_Top); // 패널라운드처리(접수)
        $c.bns.BnsPanelToGroupBox(panel_1);
        $c.bns.BnsPanelToGroupBox(panel_14);
        // BnsPanelToGroupBox(panel_T3);

        // fn_SetComboCode();

        edt_ProcsDdFrom.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 30));
        edt_ProcsDdTo.setValue($c.ut.cGetToday("yyyymmdd"));
        tab_List.setSelectedTabIndex(1);
        scwin.gridControlType("A");
        scwin.listSync(); // 목록 조회

        // 신청, 접수그리드의 신청건 배경색 변경
        scwin.changeGridBgColor();

        // 승인내역중 신청건 배경색 변경
        scwin.changeGridBgColor1();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS23500.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_List_OnSelChanged
 * @description tab List On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_List_OnSelChanged = function(nIndex) {
    try {
        // 그리드 visibility
        scwin.gridControl();
        if (nIndex === 1) {
            panel_Top.style.display = "";
            scwin.vFrnidsApplStatCd = "1";
            scwin.listSync(); // 목록 조회

        } else if (nIndex === 2) {
            panel_Top.style.display = "";
            scwin.vFrnidsApplStatCd = "2";
            scwin.listSync(); // 목록 조회

        } else if (nIndex === 3) {
            panel_Top.style.display = "none";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS23500.tab_List_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS23500.dts_List_OnLoadError" });
    }
};

