};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        // 그리드 visibility
        scwin.gridControl();
        if (row > 0) {
            // 신청상세 조회
            scwin.selectApplDtlInfo();

            // 신청스케쥴 조회
            scwin.selectApplScdList();

            // 신고담당자 조회
            scwin.selectBdchrgList();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS23500.dts_List_OnRowPosChanged" });
    }
};

