};

/**
 * @method
 * @name btn_Ret2_onclick
 * @description 「반송」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Ret2_onclick = async function() {
    try {
        if (dts_List.getRowCount() <= 0) return;

        // 승인된건은 반송 불가.
        if (dts_List.getCellData(dts_List.getRowPosition(), "FRNIDS_APPL_STAT_CD") === "3") {
            await $c.win.alert("승인처리된 건은 반송이 불가합니다.");
            return;
        }
        scwin.fn_GetPar = scwin.getReturn;
        scwin.fn_SetPar = scwin.setReturn;
        $c.bns.fn_PopReturn();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS23500.btn_Ret2_onclick" });
    }
};

