/**
 * @method
 * @name listSync
 * @description 목록조회
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    // 전체 초기화
    scwin.clearAll();
    let dsNm = 'BNS_FRNIDS_CHG_APPL_LIST';
    let qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsChgApplList';
    let param = '&{P}V_FRNIDS_APPL_STAT_CD=' + scwin.vFrnidsApplStatCd;
    $c.bns.fn_SearchBns('ULDBNS23500.xml', dts_List, dsNm, qryId, param);
    if (tab_List.getSelectedTabIndex() === 1) {
    } else {
    }
};

/**
 * @method
 * @name searchT3
 * @description 탭3 승인내역 조회
 * @returns {void}
 * @hidden N
 */
scwin.searchT3 = function() {
    // 데이터셋 초기화
    dts_ChgApplListT3.removeAll();
    dts_FrnidsSchdlListT3.removeAll();
    let dsNm = "BNS_FRNIDS_CHG_PROCS_LIST";
    let qryId = "lds.stf.bnsfrn_mgr.select.selectFrnidsChgApplList3";
    let param = "&{P}V_PROCS_DD_FROM=" + edt_ProcsDdFrom.getValue(); // 승인일자from
    param += "&{P}V_PROCS_DD_TO=" + edt_ProcsDdTo.getValue(); // 승인일자to
    param += "&{P}V_PROCS_EMP_NM=" + txb_ProcsEmpNm.getValue(); // 승인자
    param += "&{P}V_ACPT_EMP_NM=" + txb_AcptEmpNm.getValue(); // 접수자
    param += "&{P}V_ISUR_CD=" + txb_SearchIsurCd.getValue(); // 발행기관코드
    param += "&{P}V_ISUR_NM=" + txb_SearchIsurNm.getValue(); // 발행기관명
