/**
 * @method
 * @name acpt
 * @description 신청데이터를 접수 처리한다.
 * @returns {void}
 * @hidden N
 */
scwin.acpt = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "접수"))) return;
    scwin.processGp = "1"; // 접수

    let url = "/bns/IsuChgEtc.do?method=processFrnidsChgAppl";
    url += "&SCREN_ID=" + 'ULDBNS23500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&PROCESS_STAT_CD=2"; // 처리상태코드, 2 : 접수, 3 : 승인

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo, I:pInput2=dts_DtlScdList)";
    trs_Save.Post();
};

/**
 * @method
 * @name procsComplt
 * @description 처리완료 및 수정을 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procsComplt = async function() {
    if (dts_List.getCellData(dts_List.getRowPosition(), "FRNIDS_APPL_STAT_CD") === "3") {
        await $c.win.alert("이미 승인처리 되었습니다.");
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "승인"))) return;
    scwin.processGp = "3"; // 처리완료

    let url = "/bns/IsuChgEtc.do?method=processFrnidsChgAppl";
    url += "&SCREN_ID=" + 'ULDBNS23500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&PROCESS_STAT_CD=3"; // 처리상태코드, 2 : 접수, 3 : 처리완료

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo, I:pInput2=dts_DtlScdList)";
    trs_Save.Post();
};

