/**
 * @method
 * @name changeGridBgColor
 * @description 신청, 접수내역 중 변경신청 들어온 회차의 배경색을 Light Yellow로
 * @returns {void}
 * @hidden N
 */
scwin.changeGridBgColor = function() {
    // 그리드 컬럼 ID 구하기
    const arrColID = [];
    for (let i = 0; i < grd_ScdList.getTotalCol(); i++) {
        arrColID.push(grd_ScdList.getColumnID(i));
    }

    // 평가등급 일치여부가 N인 로우의 배경색 Light Yellow로 설정
    for (let j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_ScdList, arrColID[j], 'BgColor', "{decode(MODIFY_YN,'Y','#FFF7CC',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};

/**
 * @method
 * @name changeGridBgColor1
 * @description 승인내역중 신청온건의 배경색을 빨간색으로..
 * @returns {void}
 * @hidden N
 */
scwin.changeGridBgColor1 = function() {
    $c.cm.setColumnProp(grd_ScdListAf, "INT_RT_CHG_DD", 'BgColor', "{decode(FIX_DD_CHG_YN,'Y','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    $c.cm.setColumnProp(grd_ScdListAf, "INT_PAY_DD", 'BgColor', "{decode(PAY_DD_CHG_YN,'Y','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");

    // tab3
    $c.cm.setColumnProp(grd_ScdListAfT3, "INT_RT_CHG_DD", 'BgColor', "{decode(FIX_DD_CHG_YN,'Y','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    $c.cm.setColumnProp(grd_ScdListAfT3, "INT_PAY_DD", 'BgColor', "{decode(PAY_DD_CHG_YN,'Y','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
};

/**
 * @method
 * @name gridControl
 * @description 신청상태에따른 그리드 visibility
 * @returns {void}
 * @hidden N
 */
scwin.gridControl = function() {
    if (tab_List.getSelectedTabIndex() === 1) {
        scwin.gridControlType("A");
    } else {
        if (dts_List.getCellData(dts_List.getRowPosition(), "FRNIDS_APPL_STAT_CD") === "3") {
            // 승인인경우
            scwin.gridControlType("B");
        } else {
            scwin.gridControlType("A");
        }
    }
};

/**
 * @method
 * @name gridControlType
 * @description 타입에따른  그리드 visibility
 * @param {*} type type
 * @returns {void}
 * @hidden N
 */
scwin.gridControlType = function(type) {
    if (type === "A") {
        grd_ScdList.style.display = "";
        panel_3.style.display = "none";
    } else {
        grd_ScdList.style.display = "none";
        panel_3.style.display = "";
    }
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (!confirm("엑셀파일로 다운로드하시겠습니까?")) {
        return;
    }
    const excelSheet = '승인내역';
    if (dts_ListT3.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave('ULDBNS23500.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_ListT3, excelSheet, "", 8, 0);
    } else {
        await $c.win.alert("데이터가 없습니다.");
    }
};

