 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_SearchIsurCd.setValue(arrPar[0].ISUR_CD);
    txb_SearchIsurNm.setValue(arrPar[0].ISUR_NM);
};
